1	//! Generation of the Archimedean spiral ring fed to the triangulator.
2	
3	use std::f64::consts::PI;
4	
5	/// Sample `2 * n` points of a spiral whose radius grows linearly with the
6	/// parameter `t` over two full turns.
7	///
8	/// The arithmetic mirrors the C++ source term by term — `t` is the integer ratio
9	/// `i / (n * 2)` and the angle is `(4.0 * PI) * t` — so the sampled coordinates
10	/// are bit-identical doubles.
11	pub fn spiral(n: i32) -> Vec<[f64; 2]> {
12	    let count = n.wrapping_mul(2);
13	    let mut points: Vec<[f64; 2]> = Vec::new();
14	
15	    let mut i: i32 = 0;
16	    while i < count {
17	        let t = f64::from(i) / f64::from(count);
18	        let radius = t;
19	        let angle = 4.0 * PI * t;
20	        points.push([radius * angle.cos(), radius * angle.sin()]);
21	        i += 1;
22	    }
23	
24	    points
25	}
